const products=[{id:1,name:'Mayil emerald silk saree',type:'Kanchipuram silk',collection:'Silk',price:8490,old:9990,pos:'0% 0%',colour:'Emerald',tag:'Bestseller'},{id:2,name:'Gulabi rose Banarasi saree',type:'Banarasi silk',collection:'Silk',price:6290,pos:'100% 0%',colour:'Rose',tag:'New arrival'},{id:3,name:'Neelam midnight silk saree',type:'Soft silk',collection:'Festive',price:7490,pos:'0% 100%',colour:'Indigo',tag:''},{id:4,name:'Malligai ivory cotton saree',type:'Handloom cotton',collection:'Cotton',price:2490,pos:'100% 100%',colour:'Ivory',tag:'Everyday favourite'},{id:5,name:'Ananya green festive saree',type:'Silk blend',collection:'Festive',price:4590,pos:'0% 0%',colour:'Emerald',tag:''},{id:6,name:'Roja pink soft silk saree',type:'Soft silk',collection:'Silk',price:5290,pos:'100% 0%',colour:'Rose',tag:''},{id:7,name:'Nila indigo cotton saree',type:'Cotton silk',collection:'Cotton',price:3290,pos:'0% 100%',colour:'Indigo',tag:'New arrival'},{id:8,name:'Meera gold occasion saree',type:'Cotton silk',collection:'Festive',price:3890,pos:'100% 100%',colour:'Ivory',tag:''}];
const app=document.querySelector('#app');let cart=JSON.parse(localStorage.getItem('varnam-cart')||'[]'),wish=JSON.parse(localStorage.getItem('varnam-wish')||'[]'),orders=JSON.parse(localStorage.getItem('varnam-orders')||'[]'),profile=JSON.parse(localStorage.getItem('varnam-profile')||'null'),discount=false;const money=n=>'₹'+n.toLocaleString('en-IN');const pBy=id=>products.find(p=>p.id===+id);const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){localStorage.setItem('varnam-cart',JSON.stringify(cart));localStorage.setItem('varnam-wish',JSON.stringify(wish));localStorage.setItem('varnam-orders',JSON.stringify(orders));localStorage.setItem('varnam-profile',JSON.stringify(profile));const count=cart.reduce((s,x)=>s+x.qty,0);const badge=document.querySelector('#bagCount');badge.textContent=count>99?'99+':count;badge.hidden=count===0;badge.parentElement.setAttribute('aria-label',count?'Shopping bag, '+count+' item'+(count===1?'':'s'):'Shopping bag')}function toast(s){let t=document.querySelector('#toast');t.textContent=s;t.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.style.display='none',3000)}function add(id,qty=1,finish="Unstitched blouse · included"){let x=cart.find(x=>x.id===id);if(x){x.qty+=qty;x.finish=finish;}else cart.push({id,qty,finish});save();toast('Added to your bag')}function toggleWish(id){
  const selected=!wish.includes(id);
  wish=selected?[...wish,id]:wish.filter(x=>x!==id);
  save();
  if(location.hash.startsWith('#/wishlist')){render(false);return;}
  document.querySelectorAll(`[data-wish="${id}"]`).forEach(button=>{button.classList.toggle('active',selected);button.setAttribute('aria-pressed',String(selected));});
  toast(selected?'Saved to your wishlist':'Removed from your wishlist');
}function fabric(p,cls=''){return `<div class="fabric ${cls}" style="--position:${p.pos}" role="img" aria-label="${p.colour} saree with woven border"></div>`}function card(p){return `<article class="product"><a href="#/product/${p.id}">${fabric(p)}<h3>${p.name}</h3><div class="meta">${p.type}</div><div class="price">${money(p.price)}${p.old?`<span class="old">${money(p.old)}</span>`:''}</div></a>${p.tag?`<span class="tag">${p.tag}</span>`:''}<button class="heart ${wish.includes(p.id)?'active':''}" data-wish="${p.id}" aria-label="Save ${p.name} to wishlist" aria-pressed="${wish.includes(p.id)}" onclick="toggleWish(${p.id})">${icon('heart')}</button></article>`}function pageTitle(t,p=''){return `<div class="page-title"><h1>${t}</h1>${p?`<p>${p}</p>`:''}</div>`}function empty(t,p,button='Explore sarees',link='#/shop'){return `<div class="empty"><h2>${t}</h2><p class="muted">${p}</p><a class="btn" href="${link}">${button}</a></div>`}const coll=[['Silk','Silk, in its finest form','0% 0%'],['Cotton','Comfort, beautifully woven','100% 100%'],['Festive','For your brighter moments','100% 0%'],['All','A colour for every story','0% 100%']];function collectionGrid(){return `<div class="collections">${coll.map(([t,s,pos])=>`<a class="collection" href="#/shop${t==='All'?'':'?collection='+t}"><div class="fabric" style="--position:${pos}"></div><div class="caption"><h3>${t==='All'?'All sarees':t+' sarees'}</h3><small>${s} ${icon('arrow-up-right')}</small></div></a>`).join('')}</div>`}
function home(){return `<section class="hero"><div class="hero-copy"><div class="eyebrow">The heirloom edit · 2026</div><h1>Some stories<br>are woven.</h1><p>Timeless weaves. Beautiful colours.<br>Sarees to become a part of your story.</p><a class="btn" href="#/shop">Discover the collection ${icon('arrow-up-right')}</a></div><div class="hero-note">The art of tradition, the joy of being you.</div><div class="hero-counter">Silk, in its finest form</div></section><div class="benefits"><span>${icon('sparkle')} Thoughtfully selected weaves</span><span>${icon('leaf')} Made for moments that matter</span><span>${icon('truck')} Complimentary shipping over ₹3,000</span><span>${icon('heart')} A little care in every fold</span></div><section class="section"><div class="section-heading"><div><h2>Find your kind of beautiful</h2><p>From everyday rituals to extraordinary celebrations.</p></div><a class="text-link" href="#/collections">Explore collections ${icon('arrow-up-right')}</a></div>${collectionGrid()}</section><section class="section" style="padding-top:10px"><div class="section-heading"><div><h2>Loved, for a reason</h2><p>The weaves you keep coming back to.</p></div><a class="text-link" href="#/shop">Shop all sarees ${icon('arrow-up-right')}</a></div><div class="products">${products.slice(0,4).map(card).join('')}</div></section><section class="story-band"><div class="story-image" role="img" aria-label="Woman wearing burgundy silk saree in a heritage courtyard"></div><div class="story-copy"><div class="eyebrow">The heart of Varnam</div><h2>A little heritage.<br>A world of colour.</h2><p>Varnam means colour. And to us, colour is a feeling — the green of a new beginning, the gold of a celebration, the familiar comfort of a favourite saree.</p><a class="text-link" href="#/story">Get to know Varnam ${icon('arrow-up-right')}</a></div></section><section class="quote"><p>“A saree is more than what we wear.<br>It is a little of who we are.”</p><small>The Varnam philosophy</small></section>`}
function shop(params){let c=params.get('collection')||'All';return pageTitle(c==='All'?'Every weave, a new story':c+' sarees','Find something that feels beautifully like you.')+`<section class="section" style="padding-top:15px"><div class="breadcrumb"><a href="#/">Home</a> / All sarees</div><div class="shop-layout"><aside class="filters"><fieldset><h3>Collection</h3>${['All','Silk','Cotton','Festive'].map(t=>`<label><input type="radio" name="collection" value="${t}" ${c===t?'checked':''} onchange="filterShop()">${t==='All'?'All sarees':t+' sarees'}</label>`).join('')}</fieldset><fieldset><h3>Colour</h3>${['Emerald','Rose','Indigo','Ivory'].map(t=>`<label><input type="checkbox" name="colour" value="${t}" onchange="filterShop()">${t}</label>`).join('')}</fieldset><fieldset><h3>Price range</h3><label><input type="checkbox" id="budget" onchange="filterShop()">Under ₹5,000</label></fieldset><button class="text-link" style="border:0;background:none" onclick="resetFilters()">Clear filters</button></aside><div><div class="toolbar"><span id="resultsCount"></span><label>Sort by <select id="sort" onchange="filterShop()"><option value="featured">Featured</option><option value="low">Price: low to high</option><option value="high">Price: high to low</option><option value="new">Newest arrivals</option></select></label></div><div class="products" id="shopResults"></div></div></div></section>`}function filterShop(){let c=document.querySelector('[name=collection]:checked')?.value||'All',colors=[...document.querySelectorAll('[name=colour]:checked')].map(x=>x.value),sort=document.querySelector('#sort')?.value;let found=products.filter(p=>(c==='All'||p.collection===c)&&(!colors.length||colors.includes(p.colour))&&(!document.querySelector('#budget')?.checked||p.price<5000));if(sort==='low')found.sort((a,b)=>a.price-b.price);if(sort==='high')found.sort((a,b)=>b.price-a.price);if(sort==='new')found.sort((a,b)=>(b.tag==='New arrival')-(a.tag==='New arrival'));document.querySelector('#resultsCount').textContent=found.length+' sarees';document.querySelector('#shopResults').innerHTML=found.length?found.map(card).join(''):empty('No sarees match these filters','Try another colour or collection.')}
let productQty=1;function detail(id){let p=pBy(id);if(!p)return empty('Saree not found','Explore our latest collection.');productQty=1;return `<section class="section"><div class="breadcrumb"><a href="#/">Home</a> / <a href="#/shop">Sarees</a> / ${p.name}</div><div class="detail">${fabric(p)}<div><div class="eyebrow">${p.type}</div><h1>${p.name}</h1><div class="rating">${icon('sparkle')} <span class="muted">Thoughtfully selected for the Varnam collection</span></div><div class="price">${money(p.price)} ${p.old?`<span class="old">${money(p.old)}</span>`:''}</div><small class="muted">Inclusive of all taxes</small><p class="desc">A luminous ${p.colour.toLowerCase()} weave, finished with an intricate golden border. A graceful companion for celebrations, cherished moments, and everything in between.</p><div>Colour: ${p.colour}</div><div class="swatches">${products.slice(0,4).map(x=>`<a href="#/product/${x.id}" class="swatch ${x.colour===p.colour?'selected':''}" style="background:${({Emerald:'#2e6252',Rose:'#bb7c8f',Indigo:'#323d69',Ivory:'#ded2ad'})[x.colour]}" aria-label="View ${x.colour} saree"></a>`).join('')}</div><label>Choose finishing<select id="finish"><option>Unstitched blouse · included</option><option>Fall & edging · included</option></select></label><div class="buy-row"><div class="qty"><button aria-label="Decrease quantity" onclick="productQty=Math.max(1,productQty-1);document.querySelector('#pqty').textContent=productQty">${icon('minus')}</button><span id="pqty">1</span><button aria-label="Increase quantity" onclick="productQty++;document.querySelector('#pqty').textContent=productQty">${icon('plus')}</button></div><button class="btn" onclick="add(${p.id},productQty,document.querySelector('#finish').value)">Add to bag ${icon('arrow-up-right')}</button><button class="btn outline wishlist-button ${wish.includes(p.id)?'active':''}" data-wish="${p.id}" aria-label="Save ${p.name} to wishlist" aria-pressed="${wish.includes(p.id)}" onclick="toggleWish(${p.id})">${icon('heart')}</button></div><p class="muted" style="font-size:11px">Complimentary delivery on orders over ₹3,000.</p><form onsubmit="event.preventDefault();document.querySelector('#pinMsg').textContent='Demo estimate: delivery in 5–7 business days.'"><label for="pin">Check delivery availability</label><div class="checkpin"><input id="pin" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" placeholder="6-digit pincode" required><button>Check</button></div><small id="pinMsg" class="muted"></small></form><details open><summary>Details & dimensions</summary><p>Length: 5.5 metres + 0.8 metre unstitched blouse piece. Width: approximately 1.1 metres. Illustrative catalogue: final material and stock details should be confirmed before launch.</p></details><details><summary>Care for your saree</summary><p>${p.collection==='Cotton'?'Gentle cold hand wash. Dry in shade.':'Dry clean recommended. Store folded in a breathable cotton cover.'} Keep away from direct sunlight for long periods.</p></details><details><summary>Shipping & returns</summary><p>View our sample <a class="text-link" href="#/shipping">shipping & return policy</a> for details.</p></details></div></div></section><section class="section"><div class="section-heading"><h2>You might also love</h2></div><div class="products">${products.filter(x=>x.id!==p.id).slice(0,4).map(card).join('')}</div></section>`}
const subtotal=()=>cart.reduce((s,x)=>s+pBy(x.id).price*x.qty,0);function summary(checkout=false){let s=subtotal(),d=discount?Math.round(s*.1):0,shipping=s>=3000?0:150;return `<aside class="summary-box"><h2>Your order</h2>${checkout?cart.map(x=>`<div class="summary-row"><span>${pBy(x.id).name} × ${x.qty}</span><span>${money(pBy(x.id).price*x.qty)}</span></div>`).join(''):''}<div class="summary-row"><span>Subtotal</span><span>${money(s)}</span></div><div class="summary-row"><span>Delivery</span><span>${shipping?money(shipping):'Complimentary'}</span></div>${d?`<div class="summary-row"><span>WELCOME10</span><span>−${money(d)}</span></div>`:''}<div class="summary-row total"><span>Total</span><span>${money(s-d+shipping)}</span></div>${!checkout?`<a class="btn" href="#/checkout">Continue to checkout ${icon('arrow-up-right')}</a><small>Taxes included in the total.</small><form class="coupon" onsubmit="event.preventDefault();applyCoupon()"><label for="coupon">Have a little gift code?</label><div class="inline"><input id="coupon" placeholder="Try WELCOME10"><button>Apply</button></div></form>`:'<small>Demo checkout · no payment is collected.</small>'}</aside>`}function applyCoupon(){if(document.querySelector('#coupon').value.trim().toUpperCase()==='WELCOME10'){discount=true;render(false);toast('10% welcome discount applied')}else toast('Use WELCOME10 for this demo')}function changeQty(id,delta){let x=cart.find(x=>x.id===id);x.qty=Math.max(1,x.qty+delta);save();render(false)}function removeItem(id){cart=cart.filter(x=>x.id!==id);save();render(false)}function cartPage(){return pageTitle('Your bag','A few beautiful things, just for you.')+(cart.length?`<section class="section" style="padding-top:10px"><div class="cart-layout"><div>${cart.map(x=>{let p=pBy(x.id);return `<div class="cart-item"><a href="#/product/${p.id}">${fabric(p)}</a><div><h3><a href="#/product/${p.id}">${p.name}</a></h3><p class="meta muted">${p.type} · ${p.colour}<br>${escape(x.finish||"Unstitched blouse · included")}</p><div class="qty"><button aria-label="Decrease quantity" onclick="changeQty(${p.id},-1)">${icon('minus')}</button><span>${x.qty}</span><button aria-label="Increase quantity" onclick="changeQty(${p.id},1)">${icon('plus')}</button></div><button class="remove" onclick="removeItem(${p.id})">Remove</button></div><div class="price">${money(p.price*x.qty)}</div></div>`}).join('')}<p><a class="text-link" href="#/shop">Continue exploring</a></p></div>${summary()}</div></section>`:empty('Your next favourite is waiting','Your bag is empty. Find a weave to make your own.'))}
function checkout(){if(!cart.length)return pageTitle('Checkout')+empty('Your bag is empty','Add a saree to begin checkout.');return pageTitle('A step closer to beautiful','Bag / Delivery / Demo order')+`<section class="section" style="padding-top:10px"><div class="cart-layout"><form id="checkoutForm"><h2>Contact & delivery</h2><div class="form-grid"><label>First name<input name="first" autocomplete="given-name" required></label><label>Last name<input name="last" autocomplete="family-name" required></label><label class="wide">Email address<input name="email" type="email" autocomplete="email" required></label><label class="wide">Phone number<input name="phone" type="tel" autocomplete="tel" pattern="[0-9+ ()-]{10,16}" required></label><label class="wide">Street address<input name="address" autocomplete="address-line1" required></label><label class="wide">Apartment, landmark (optional)<input name="apartment" autocomplete="address-line2"></label><label>City<input name="city" autocomplete="address-level2" required></label><label>Pincode<input name="pin" inputmode="numeric" autocomplete="postal-code" pattern="[0-9]{6}" maxlength="6" required></label><label>State<input name="state" autocomplete="address-level1" required></label><label>Country<select name="country" autocomplete="country-name"><option>India</option></select></label></div><h3>Delivery method</h3><label><input type="radio" checked name="delivery"> Standard delivery · 5–7 business days</label><h3>Payment</h3><div class="demo-note">This is a sample shopping experience. Place a demo order to preview the confirmation and tracking screens. No payment is taken and no real shipment is created.</div><button class="btn" style="width:100%;margin-top:24px">Place demo order ${icon('arrow-up-right')}</button></form>${summary(true)}</div></section>`}function placeOrder(e){e.preventDefault();let f=new FormData(e.target),id='VRN'+Date.now().toString().slice(-7);orders.unshift({id,date:new Date().toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'}),name:f.get('first'),items:[...cart],total:subtotal()-(discount?Math.round(subtotal()*.1):0)+(subtotal()>=3000?0:150)});cart=[];discount=false;save();location.hash='/confirmation/'+id}function confirmation(id){let o=orders.find(x=>x.id===id);if(!o)return empty('Order not found','You can create a demo order from your bag.');return `<section class="confirmation"><span class="tick">${icon('check')}</span><h1>A beautiful choice, ${escape(o.name)}.</h1><p>Your demo order <strong>${o.id}</strong> is confirmed.</p><p class="muted">This sample order is saved on this browser. No payment, email, or shipment has been created.</p><div class="order-card"><div class="summary-row"><span>Order total</span><strong>${money(o.total)}</strong></div>${o.items.map(x=>`<div class="summary-row"><span>${pBy(x.id).name} × ${x.qty}</span><span>${money(pBy(x.id).price*x.qty)}</span></div>`).join('')}</div><a class="btn" href="#/track?order=${o.id}">View demo tracking</a><p><a class="text-link" href="#/shop">Keep exploring</a></p></section>`}
function auth(mode){let signup=mode==='signup';return pageTitle(signup?'Make yourself at home':'Welcome back','Your colours. Your favourites. Your Varnam.')+`<div class="auth"><div class="tabs"><a href="#/login">Sign in</a><a href="#/signup">Create account</a></div><p class="demo-note">Demo profile saved in this browser. No online account is created.</p><form id="authForm">${signup?'<label>Your name<input name="name" autocomplete="name" required></label>':''}<label>Email address<input name="email" type="email" autocomplete="email" required></label><button class="btn">${signup?'Create demo profile':'Continue with demo profile'}</button></form><p>No password needed for this preview.</p></div>`}function account(){if(!profile)return auth('login');return pageTitle('Hello, '+escape(profile.name),'A little corner of Varnam, just for you.')+`<section class="section"><div class="account-layout"><aside class="account-menu"><a href="#/account">My account</a><a href="#/orders">My orders</a><a href="#/wishlist">My wishlist</a><a href="#/addresses">My addresses</a><a href="#/" onclick="profile=null;save()">Sign out</a></aside><div><h2>Your profile</h2><p>${escape(profile.name)}<br><span class="muted">${escape(profile.email)}</span></p><p class="demo-note">This profile exists only on this browser.</p><h2 style="margin-top:30px">Recent orders</h2>${orderList()}</div></div></section>`}function orderList(){return orders.length?orders.map(o=>`<div class="order-card"><h3>${o.id} <span class="muted" style="font-size:11px">· Demo order</span></h3><p>${o.date} · ${o.items.reduce((s,x)=>s+x.qty,0)} item(s) · ${money(o.total)}</p><a class="text-link" href="#/track?order=${o.id}">View order & tracking</a></div>`).join(''):empty('Your stories start here','You have no demo orders yet.')}function track(params){let id=params.get('order')||'';return pageTitle('Follow your saree’s journey','Preview tracking for a demo order placed on this browser.')+`<div class="auth"><form id="trackForm"><label>Order number<input name="order" value="${escape(id)}" placeholder="e.g. VRN1234567" required></label><button class="btn">Find demo order</button></form><div id="trackResult" style="margin-top:30px"></div></div>`}function trackResult(id){let o=orders.find(x=>x.id===id);document.querySelector('#trackResult').innerHTML=o?`<h2 style="font-size:24px">${o.id}</h2><p class="demo-note">Demo status only. No real shipment exists.</p><div class="status-step"><h3>Order placed</h3><p>${o.date} · Your demo order is confirmed.</p></div><div class="status-step"><h3>Preparing your saree</h3><p>Preview of the next fulfilment step.</p></div><div class="status-step"><h3>On its way</h3><p>Shipping updates will appear here when connected.</p></div><a class="text-link" href="#/confirmation/${o.id}">View order details</a>`:'<p>No demo order found. Check your order number and use the browser where you placed it.</p>'}
const faqs=[['How do I choose the right saree?','Cotton is light and comfortable for everyday wear. Silk brings richness to festive occasions. Use our collection and colour filters to find your style.'],['Does the saree include a blouse piece?','Our sample catalogue includes an unstitched blouse piece. Each product screen lists its dimensions and finishing options.'],['How do I care for silk sarees?','Dry clean silk sarees and store them in a breathable cotton cover. Refold occasionally and avoid prolonged direct sunlight.'],['Can I place a real order?','This website is a demo. Checkout creates a sample order on your browser. Inventory, payments, shipping and customer accounts need to be connected before selling.'],['Will the colour look exactly like the photo?','Screen settings and lighting can change how colours appear. These campaign and catalogue images are illustrative generated photography.'],['Where can I find delivery and return details?','Visit Shipping & returns for a proposed policy. The business must confirm and approve its final policy before accepting real orders.']];
function prosePage(title,html,sub=''){return pageTitle(title,sub)+`<article class="prose">${html}</article>`}function story(){return pageTitle('Colour is where our story begins','Varnam · A celebration of six yards')+`<section class="story-band"><div class="story-image"></div><div class="story-copy"><h2>Tradition, with room<br>for your own story.</h2><p>Some colours feel like home. Others invite us to become someone new. Varnam is imagined as a place for both: a collection of sarees for everyday rhythms and once-in-a-lifetime moments.</p><p>Our name means colour. Our idea is simple — finding a saree should feel as joyful as wearing it.</p><a class="btn" href="#/shop">Find your colours</a></div></section><article class="prose"><h2>A weave for every chapter</h2><p>From the ease of cotton to the luminous richness of silk, our collection brings different moods together. Thoughtful details, a considered palette, and the enduring beauty of the saree guide the Varnam experience.</p><p class="demo-note">Brand concept and illustrative catalogue. Supplier, artisan and material claims should be verified with the business before launch.</p></article>`}const articles=[{t:'Finding your first silk saree',p:'A guide to texture, drape, and the colours you return to.',body:'Start with how you want to feel. Soft silk drapes easily; a structured silk holds its form. Choose a colour that complements the blouses you already own, then look closely at the border and pallu. A saree you can imagine wearing in several different ways is often a beautiful first choice.'},{t:'A little care goes a long way',p:'Simple rituals to keep your favourite weaves beautiful.',body:'Air your saree after wearing it. Store silk in a breathable cover, away from strong light and moisture. Avoid placing perfume directly on the fabric. Check the care instructions for each material, and use professional dry cleaning for delicate silk and zari.'},{t:'The everyday joy of cotton',p:'Light, breathable, and beautifully yours.',body:'Cotton brings quiet comfort to busy days. Pair a simple weave with a contrasting blouse, or keep the palette soft and tonal. A neat pleat and comfortable footwear make it easy to move through the day. Hand wash gently when permitted by the care label, and dry in shade.'}];function journal(){return pageTitle('The Varnam journal','A few stories, a little inspiration, and the joy of six yards.')+`<section class="section"><div class="journal-grid">${articles.map((a,i)=>`<a class="journal-card" href="#/journal/${i+1}">${fabric(products[i])}<h2>${a.t}</h2><p>${a.p}</p><span class="text-link">Read the story ${icon('arrow-up-right')}</span></a>`).join('')}</div></section>`}
function render(scroll=true){let [raw,query='']=(location.hash.slice(1)||'/').split('?'),parts=raw.split('/').filter(Boolean),route=parts[0]||'home',params=new URLSearchParams(query);setMenu(false);let html='';switch(route){case'home':html=home();break;case'shop':html=shop(params);break;case'collections':html=pageTitle('A world of weaves','Find the collection that speaks to you.')+`<section class="section">${collectionGrid()}</section>`;break;case'product':html=detail(parts[1]);break;case'cart':html=cartPage();break;case'wishlist':html=pageTitle('Your little loves','Keep your favourite colours close.')+(wish.length?`<section class="section"><div class="products">${wish.map(id=>card(pBy(id))).join('')}</div></section>`:empty('Love at first weave?','Tap the heart on a saree to save it here.'));break;case'checkout':html=checkout();break;case'confirmation':html=confirmation(parts[1]);break;case'login':case'signup':html=auth(route);break;case'account':html=account();break;case'orders':html=pageTitle('Your orders','Your Varnam stories, all in one place.')+`<section class="prose">${orderList()}</section>`;break;case'addresses':html=pageTitle('Your addresses','Saved in this browser for this demo.')+`<div class="auth"><form id="addressForm"><label>Address nickname<input name="label" value="${escape(localStorage.getItem('varnam-address-label')||'Home')}" required></label><label>Full address<textarea name="address" required>${escape(localStorage.getItem('varnam-address')||'')}</textarea></label><button class="btn">Save address</button></form></div>`;break;case'track':html=track(params);break;case'story':html=story();break;case'journal':html=parts[1]?prosePage(articles[+parts[1]-1]?.t||'Story not found',`<p>${articles[+parts[1]-1]?.body||'Explore our journal for more stories.'}</p><a class="text-link" href="#/journal">Back to the journal</a>`):journal();break;case'faq':html=prosePage('A little help',faqs.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join(''),'Answers to the questions on your mind.');break;case'shipping':html=prosePage('Shipping & returns',`<p class="demo-note">Proposed policy for the store preview. Confirm these terms before launching real sales.</p><h2>Delivery, with care</h2><p>Standard delivery within India is estimated at 5–7 business days. The demo offers complimentary delivery on orders over ₹3,000; otherwise, a ₹150 delivery charge applies.</p><h2>Returns & exchanges</h2><p>Proposed return window: 7 days from delivery for unworn, unwashed sarees with tags and original packaging. Custom finishing would be excluded except for defects. The business should confirm return shipping costs and refund timelines.</p><h2>Need a hand?</h2><p><a class="text-link" href="#/contact">Contact Varnam</a> for questions about your order. Demo orders do not create shipments.</p>`);break;case'privacy':html=prosePage('Privacy',`<h2>Your data in this preview</h2><p>The demo stores your bag, wishlist, profile, address and sample orders in your browser’s local storage. These entries are not submitted to a store backend. Anyone using this browser may be able to view them.</p><h2>External services</h2><p>Fonts are served by Google Fonts. Site hosting may process access information under its own policies. The newsletter and contact forms show local confirmation only.</p><h2>Clear your demo data</h2><p>Use the button below to remove Varnam’s saved entries from this browser.</p><button class="btn outline" onclick="clearDemo()">Clear demo data</button><h2>Before the store launches</h2><p>A final privacy policy must describe the actual payment, fulfilment, analytics and support providers used by the business.</p>`);break;case'terms':html=prosePage('Terms of use',`<h2>A store concept</h2><p>Varnam is a demonstration storefront. Prices, product descriptions, images and policies are illustrative. No commercial sale takes place when a demo order is submitted.</p><h2>Images & catalogue</h2><p>Campaign and fabric images are AI generated. Similar colour variants share illustrative photography. Real product photos and verified specifications should replace these before launch.</p><h2>Orders & payment</h2><p>No payment details are requested or processed. Confirmation screens and tracking statuses refer only to sample orders created on your browser.</p>`);break;case'contact':html=pageTitle('Let’s talk sarees','A question, a colour, a little guidance — we’re here.')+`<section class="section"><div class="contact-layout"><div><h2>A little help finding<br>your beautiful.</h2><p class="muted">Tell us about the occasion or the weave you have in mind.</p><p class="demo-note">Contact details will be added when the business launches. This form previews a message confirmation; it does not send a message.</p><p><a class="text-link" href="#/faq">Browse common questions</a></p></div><form id="contactForm"><div class="form-grid"><label>Your name<input name="name" autocomplete="name" required></label><label>Email address<input type="email" name="email" autocomplete="email" required></label><label class="wide">What can we help with?<select name="topic"><option>Choosing a saree</option><option>Order question</option><option>Care & materials</option><option>Something else</option></select></label><label class="wide">Your message<textarea name="message" required></textarea></label></div><button class="btn">Preview message submission</button><p id="contactMsg" role="status"></p></form></div></section>`;break;case'search':html=pageTitle('Find your colours','Search by colour, weave, or saree name.')+`<section class="section"><form class="search-box" id="searchForm"><label class="sr" for="search">Search sarees</label><div class="inline"><input type="search" id="search" placeholder="Try silk, emerald, cotton…" autofocus><button>Search</button></div></form><div class="products" id="searchResults" style="margin-top:35px"></div></section>`;break;default:html=pageTitle('This page has wandered away')+empty('Let’s find your way back','There are beautiful weaves waiting.','Back to Varnam','#/')}app.innerHTML=html;document.title=(route==='home'?'Varnam | Sarees, woven with stories':route.charAt(0).toUpperCase()+route.slice(1)+' | Varnam');save();if(route==='shop')filterShop();if(route==='track'&&params.get('order'))trackResult(params.get('order'));document.querySelectorAll('input[type=email],input[type=search],#coupon').forEach(x=>{x.autocapitalize='off';x.spellcheck=false});document.querySelectorAll('form').forEach(form=>{if(form.id!=='searchForm')form.method='post';form.querySelectorAll('input,textarea,select').forEach((x,i)=>{if(!x.name)x.name=x.id||'field'+i;if(x.required)x.setAttribute('aria-required','true')});});document.querySelector('#checkoutForm')?.addEventListener('submit',placeOrder);document.querySelector('#authForm')?.addEventListener('submit',e=>{e.preventDefault();let f=new FormData(e.target);profile={name:f.get('name')||String(f.get('email')).split('@')[0],email:f.get('email')};save();location.hash='/account'});document.querySelector('#contactForm')?.addEventListener('submit',e=>{e.preventDefault();document.querySelector('#contactMsg').textContent='Message preview complete. No message has been sent.';e.target.reset()});document.querySelector('#addressForm')?.addEventListener('submit',e=>{e.preventDefault();let f=new FormData(e.target);localStorage.setItem('varnam-address',f.get('address'));localStorage.setItem('varnam-address-label',f.get('label'));toast('Address saved on this browser')});document.querySelector('#trackForm')?.addEventListener('submit',e=>{e.preventDefault();trackResult(new FormData(e.target).get('order').trim())});document.querySelector('#searchForm')?.addEventListener('submit',e=>{e.preventDefault();searchProducts()});document.querySelector('#search')?.addEventListener('input',searchProducts);if(route==='search')searchProducts();if(scroll)window.scrollTo(0,0)}function searchProducts(){let q=document.querySelector('#search').value.trim().toLowerCase(),found=products.filter(p=>(p.name+' '+p.type+' '+p.collection).toLowerCase().includes(q));document.querySelector('#searchResults').innerHTML=found.length?found.map(card).join(''):empty('No weaves found','Try a colour or material, such as rose or silk.')}function clearDemo(){for(let k of ['cart','wish','orders','profile','address','address-label'])localStorage.removeItem('varnam-'+k);cart=[];wish=[];orders=[];profile=null;save();toast('Demo data cleared')}
document.querySelector('#newsletter').addEventListener('submit',e=>{e.preventDefault();document.querySelector('#newsMsg').textContent='Subscription preview complete. No email has been sent or saved.';e.target.reset()});window.addEventListener('hashchange',()=>render());render();

function resetFilters(){document.querySelector('[name=collection][value=All]').checked=true;document.querySelectorAll('[name=colour],#budget').forEach(x=>x.checked=false);document.querySelector('#sort').value='featured';filterShop()}
